'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courses={g10:'Grade 10 · MYP Mathematics',g11:'Grade 11 · Mathematics AA HL',g12:'Grade 12 · Mathematics AA SL'};
const criteria={A:'Knowing & understanding',B:'Investigating patterns',C:'Communicating',D:'Applying mathematics'};
const split=v=>String(v??'').split(';').map(s=>s.trim()).filter(Boolean);
const number=(v,max)=>{if(v===null||v===undefined||String(v).trim()==='')return null;const n=Number(v);return Number.isInteger(n)&&n>=(max===8?0:1)&&n<=max?n:null};
const dateValue=v=>{if(!v)return null;if(typeof v==='number')return new Date(Math.round((v-25569)*86400000)).toISOString().slice(0,10);if(v instanceof Date)return v.toISOString().slice(0,10);const s=String(v);if(/^\d{4}-\d\d-\d\d/.test(s))return s.slice(0,10);return null};
function normalize(rows,course){const g=course==='g10',max=g?8:7;return rows.filter(r=>r[0]!=null&&String(r[0]).trim()).map((r,i)=>{const cs=g?split(r[8]):['Overall'],scores={};cs.forEach((c,j)=>{if((g&&!criteria[c])||j>1)return;scores[c]={predicted:number(r[g?10+j:9],max),actual:number(r[g?12+j:10],max)}});const warnings=[];if(g&&cs.length===1&&(r[11]!=null||r[13]!=null))warnings.push('A second score was entered without a second criterion. It is excluded.');const date=dateValue(r[g?6:5]);if(!date)warnings.push('Assessment date is missing.');if(date&&date>new Date().toISOString().slice(0,10))warnings.push('Assessment date is in the future. Check the source date.');return{id:String(r[0]),student:String(r[3]||r[4]||'Unknown student').trim().toLowerCase(),name:String(r[4]||r[3]||'Unknown student'),course,group:g?String(r[5]||''):'',date,prepared:String(r[g?7:6]||''),strategies:split(r[g?9:7]),topic:g?cs.map(c=>`${c} · ${criteria[c]||'Unmapped'}`).join(', '):String(r[8]||''),scores,mistakes:split(r[g?14:11]),well:String(r[g?15:12]||''),challenge:String(r[g?16:13]||''),plan:String(r[g?17:14]||''),warnings,order:i}})}
function demo(){const out={g10:[],g11:[],g12:[]};for(const course of Object.keys(out))out[course]=normalize(window.REFLECTION_SAMPLE_DATA.workbooks[course],course);return out}
let data=demo(),isDemo=true,view='student';
function opts(el,list,selected){el.innerHTML=list.map(([v,t])=>`<option value="${esc(v)}">${esc(t)}</option>`).join('');if(list.some(([v])=>v===selected))el.value=selected}
opts($('course'),Object.entries(courses));
function records(){return data[$('course').value]||[]}
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Date missing';
function selection(){const r=records().filter(r=>r.student===$('student').value).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.order-b.order);return{all:r,current:r.find(r=>r.id===$('assessment').value)||r.at(-1)}}
function setupStudents(){const prev=$('student').value,map=new Map(records().map(r=>[r.student,r.name]));opts($('student'),[...map].sort((a,b)=>a[1].localeCompare(b[1])),prev);setupAssessments()}
function setupAssessments(){const rows=records().filter(r=>r.student===$('student').value).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.order-b.order);opts($('assessment'),rows.map(r=>[r.id,`${dateLabel(r.date)} · ${r.topic.slice(0,65)} · #${r.id}`]),rows.filter(r=>r.date).at(-1)?.id||rows.at(-1)?.id);setupCriteria()}
function setupCriteria(){const prev=$('criterion').value,g=$('course').value==='g10';$('criterionField').hidden=!g;const cs=g?[...new Set((view==='class'?records():selection().all).flatMap(r=>Object.keys(r.scores)))].sort():['Overall'];opts($('criterion'),cs.map(c=>[c,criteria[c]?`${c} · ${criteria[c]}`:c]),prev);render()}
function stats(rows,c){const p=rows.map(r=>r.scores[c]).filter(s=>s&&s.predicted!==null&&s.actual!==null),n=p.length,g=p.map(s=>s.actual-s.predicted);return{n,exact:g.filter(x=>x===0).length,close:g.filter(x=>Math.abs(x)<=1).length,mean:n?g.reduce((a,b)=>a+Math.abs(b),0)/n:null,gaps:g}}
function metrics(s){return `<div class="metrics"><div class="metric"><strong>${s.n?Math.round(s.exact/s.n*100)+'%':'—'}</strong><span>Exact matches</span><small>${s.exact} of ${s.n} complete pairs</small></div><div class="metric"><strong>${s.n?Math.round(s.close/s.n*100)+'%':'—'}</strong><span>Within 1 level</span><small>${s.close} of ${s.n} complete pairs</small></div><div class="metric"><strong>${s.mean===null?'—':s.mean.toFixed(1)}</strong><span>Average distance</span><small>achievement levels</small></div></div>`}
function chart(rows,c,max){const w=580,h=210,p={l:27,r:15,t:15,b:43},dated=rows.filter(r=>r.date),x=i=>p.l+(dated.length===1?(w-p.l-p.r)/2:i*(w-p.l-p.r)/Math.max(1,dated.length-1)),y=n=>h-p.b-n*(h-p.t-p.b)/max;let svg='';for(let n=0;n<=max;n+=max===8?2:1)svg+=`<line x1="${p.l}" y1="${y(n)}" x2="${w-p.r}" y2="${y(n)}" stroke="#e9ede7"/><text x="5" y="${y(n)+3}">${n}</text>`;for(const [field,color,dash] of [['predicted','#b3c0b0','4 4'],['actual','#29755d','']]){let prev=null;dated.forEach((r,i)=>{const n=r.scores[c]?.[field];if(n==null){prev=null;return}if(prev)svg+=`<line x1="${prev.x}" y1="${prev.y}" x2="${x(i)}" y2="${y(n)}" stroke="${color}" stroke-width="2" stroke-dasharray="${dash}"/>`;svg+=`<circle cx="${x(i)}" cy="${y(n)}" r="4" fill="${color}"><title>${esc(dateLabel(r.date))} #${esc(r.id)} · ${field}: ${n}/${max}</title></circle>`;prev={x:x(i),y:y(n)}})}dated.forEach((r,i)=>{svg+=`<text x="${x(i)}" y="${h-24}" text-anchor="middle">${esc(dateLabel(r.date).replace(/ 202\d/,''))}</text><text x="${x(i)}" y="${h-10}" text-anchor="middle">#${esc(r.id)}</text>`});return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Predicted and actual achievement levels across ${dated.length} dated responses. Full values are in the assessment table below.">${svg}</svg><div class="legend"><span>Actual result</span><span>My estimate</span></div>`}
const tagList=a=>a.length?a.map(t=>`<span class="tag">${esc(t)}</span>`).join(''):'<span class="small">Not recorded</span>';
function routine(r){const text=[r.challenge,r.plan,...r.mistakes].join(' ').toLowerCase();if(/\btime\b|\bfinish\w*/.test(text))return[['Plan the time','Try a short mixed set in two sessions. Allocate time to each question before you start.'],['Check your pace','At the midpoint, check progress. If stuck, mark the question and return after the others.'],['Review and retry','Compare with the worked solutions. Retry one unfinished question in the next session.']];if(/formula|concept|understand|unfamiliar/.test(text))return[['Recall first','Without notes, write the key ideas for the topics you found challenging. Check and fill the gaps.'],['Mix your practice','Across two sessions, solve a small set from different topics. Explain why your chosen method fits.'],['Check and retry','Compare with the worked solution. Label the cause of an error, then retry the question next session.']];return[['Read with a purpose','Before solving three mixed questions, underline what each asks and identify the information you need.'],['Make the method visible','Write the method before calculating. Check signs, units, rounding, and whether the answer fits the prompt.'],['Learn from the check','After your attempt, compare with a worked solution. Retry one missed question in a second session.']]}
function planKey(r){return 'math-reflection-plan:'+r.course+':'+r.student+':'+r.id}
function readPlan(r){try{return localStorage.getItem(planKey(r))||r.plan}catch{return r.plan}}
function studentHTML(){const {all,current:r}=selection();if(!r)return '<div class="card empty">No student responses yet. Import a workbook to get started.</div>';const c=$('criterion').value,max=r.course==='g10'?8:7,history=all.filter(x=>x.scores[c]&&(r.date?x.date&&x.date<=r.date:true)),s=stats(history,c),score=r.scores[c],gap=score?.actual!=null&&score?.predicted!=null?score.actual-score.predicted:null,rs=routine(r);$('notice').innerHTML=r.warnings.length?`<div class="warning">${r.warnings.map(esc).join('<br>')}</div>`:'';return `<div class="section-label">THIS ASSESSMENT <span>${esc(dateLabel(r.date))} · response #${esc(r.id)}</span></div><div class="grid-top"><section class="card"><div class="card-heading"><h2><span class="step">01</span>How I prepared</h2><span class="small">${esc(r.group)}</span></div><div class="prepared">${esc(r.prepared||'Not recorded')}</div><div class="small">${esc(r.topic)}</div><p class="small" style="margin-bottom:0;margin-top:22px">STRATEGIES I USED</p><div class="tags">${tagList(r.strategies)}</div></section><section class="card"><div class="card-heading"><h2><span class="step">02</span>Expected → actual</h2><span class="small">${c==='Overall'?'Achievement level':'Criterion '+esc(c)}</span></div><div class="score-row"><div class="score-block"><small>MY ESTIMATE</small><div class="score">${score?.predicted??'—'}<em>/ ${max}</em></div></div><span class="arrow">→</span><div class="score-block"><small>MY RESULT</small><div class="score actual">${score?.actual??'—'}<em>/ ${max}</em></div></div></div><div class="gap-note">${gap===null?'A complete predicted and actual pair is not available.':gap===0?'Matched my estimate · 0 levels off':`${Math.abs(gap)} level${Math.abs(gap)===1?'':'s'} ${gap>0?'above':'below'} my estimate`}</div>${r.course==='g10'?`<div class="small" style="margin-top:10px">${Object.entries(r.scores).map(([k,v])=>`${esc(k)}: ${v.predicted??'—'} → ${v.actual??'—'} / 8`).join(' &nbsp; · &nbsp; ')}</div>`:''}</section></div><div class="section-label">MY HISTORY & REFLECTION</div><div class="grid-bottom"><section class="card"><div class="card-heading"><h2>${c==='Overall'?'My assessment history':'Criterion '+esc(c)+' history'}</h2><span class="small">out of ${max}</span></div>${history.some(x=>x.date)?chart(history,c,max):'<p class="empty">No dated results for this criterion yet.</p>'}<p class="muted-note">${r.course==='g10'?'Only this criterion is compared.':'Topics and papers may differ. Use these results as context.'} Missing results are left blank.</p><div class="card-heading" style="margin:25px 0 0"><h2>Prediction check</h2><span class="small">${s.n} complete pairs</span></div>${metrics(s)}<div class="gap-strip">${history.map(x=>{const v=x.scores[c],d=v.actual!==null&&v.predicted!==null?v.actual-v.predicted:null;return `<div class="gap-pill"><small>${esc(dateLabel(x.date).replace(/ 202\d/,''))} · #${esc(x.id)}</small><b>${d===null?'—':d>0?'+'+d:d}</b></div>`}).join('')}</div><p class="small">Gap = actual − predicted. Positive: higher than expected. Negative: lower. Zero: matched.</p><details><summary class="small">View assessment values (${history.length})</summary><div class="table-wrap"><table><thead><tr><th>Date / response</th><th>Topic</th><th>Predicted</th><th>Actual</th></tr></thead><tbody>${history.map(x=>`<tr><td>${esc(dateLabel(x.date))} #${esc(x.id)}</td><td>${esc(x.topic)}</td><td>${x.scores[c].predicted??'—'}</td><td>${x.scores[c].actual??'—'}</td></tr>`).join('')}</tbody></table></div></details>${all.some(x=>!x.date)?'<p class="small">Undated responses can be selected above; they are excluded from dated history.</p>':''}</section><section class="card"><div class="card-heading"><h2>What I noticed</h2></div><div class="reflection-item"><h3>WHAT WENT WELL</h3><p>${esc(r.well||'Not recorded')}</p></div><div class="reflection-item"><h3>WHAT WAS CHALLENGING</h3><p>${esc(r.challenge||'Not recorded')}</p></div><div class="reflection-item"><h3>MISTAKES TO LEARN FROM</h3><div class="tags">${tagList(r.mistakes)}</div></div><div class="reflection-item"><h3>MY OWN REFLECTION</h3><p>${esc(r.plan||'Not recorded')}</p></div></section></div><section class="plan"><div class="plan-head"><div><p class="eyebrow">SMALL ACTIONS, STEADY PRACTICE</p><h2>My next move</h2><div class="small">Suggested from the difficulties in this reflection. Make it your own.</div></div><button class="quiet" id="editPlan">Edit my plan ↗</button></div><div class="plan-grid">${rs.map(([t,p],i)=>`<div class="plan-step"><b>0${i+1} · ${t}</b><p>${p}</p></div>`).join('')}</div><details id="planDetails" class="plan-editor"><summary class="small">My practice plan</summary><label for="planText">What will I do, when will I do it, and how will I know it helped?</label><textarea id="planText">${esc(readPlan(r))}</textarea><button id="savePlan" class="primary" style="margin-top:10px">Save on this device</button><span id="saveStatus" class="saved" role="status"></span></details></section>`}
function bars(rows,field){const counts=new Map();rows.forEach(r=>new Set(r[field]).forEach(s=>counts.set(s,(counts.get(s)||0)+1)));return [...counts].sort((a,b)=>b[1]-a[1]).slice(0,7).map(([k,n])=>`<div class="bar-row"><div><span>${esc(k)}</span><span>${n} / ${rows.length}</span></div><div class="bar"><i style="width:${rows.length?n/rows.length*100:0}%"></i></div></div>`).join('')||'<p class="small">No selections recorded.</p>'}
function classHTML(){const c=$('criterion').value;let rows=records();const dates=[...new Set(rows.map(r=>r.date||'undated'))].sort(),requested=$('classDate')?.value||'all',prev=dates.includes(requested)?requested:'all';let filtered=prev==='all'?rows:rows.filter(r=>(r.date||'undated')===prev),s=stats(filtered,c),warnings=rows.filter(r=>r.warnings.length).length;return `<div class="card" style="margin-bottom:20px"><div class="card-heading"><h2>What we can work on together</h2><label class="small">Assessment date<select id="classDate"><option value="all">All recorded dates</option>${dates.map(d=>`<option value="${d}" ${prev===d?'selected':''}>${esc(d==='undated'?'Date missing':dateLabel(d))}</option>`).join('')}</select></label></div><p class="small">${new Set(filtered.map(r=>r.student)).size} students · ${filtered.length} responses · ${c==='Overall'?'overall scores':'Criterion '+esc(c)}. ${prev==='all'?'Multiple assessments are combined; use the date filter to focus the comparison.':''}</p>${metrics(s)}<p class="small">${warnings} response${warnings===1?' has':'s have'} a date or criterion warning. Only complete score pairs for the selected criterion enter the prediction check. Strategy frequency does not establish effectiveness.</p></div><div class="grid-top"><section class="card"><div class="card-heading"><h2>Common mistakes</h2></div>${bars(filtered,'mistakes')}</section><section class="card"><div class="card-heading"><h2>Preparation strategies</h2></div>${bars(filtered,'strategies')}</section></div><div class="card" style="margin-top:20px"><h2 style="font-size:15px">Import review</h2><p class="small">${rows.length} responses loaded. No source values were changed. Second scores without a second criterion remain excluded.</p><div class="table-wrap"><table><thead><tr><th>Response</th><th>Recorded date</th><th>Review note</th></tr></thead><tbody>${rows.filter(r=>r.warnings.length).map(r=>`<tr><td>#${esc(r.id)}</td><td>${esc(dateLabel(r.date))}</td><td>${r.warnings.map(esc).join(' ')}</td></tr>`).join('')||'<tr><td colspan="3">No date or criterion warnings.</td></tr>'}</tbody></table></div></div>`}
function render(){const g=$('course').value==='g10';$('modeBadge').textContent=isDemo?'Illustrative demo':'Imported · private session';$('studentField').hidden=view==='class';$('assessmentField').hidden=view==='class';$('criterionField').hidden=!g;$('viewLabel').textContent=view==='class'?'Class overview':'Student reflection';$('studentTab').classList.toggle('active',view==='student');$('classTab').classList.toggle('active',view==='class');$('notice').innerHTML='';const html=view==='class'?classHTML():studentHTML();$('content').innerHTML=html;if(view==='class'){$('classDate').onchange=render}else{if($('editPlan'))$('editPlan').onclick=()=>{$('planDetails').open=true;$('planText').focus()};if($('savePlan'))$('savePlan').onclick=()=>{try{localStorage.setItem(planKey(selection().current),$('planText').value);$('saveStatus').textContent='Saved on this device.'}catch{$('saveStatus').textContent='This browser could not save the plan.'}}}}
function importPack(pack){if(pack.version!==1||!pack.workbooks)throw new Error('This data pack format is not supported.');const next={};for(const [k,rows] of Object.entries(pack.workbooks)){if(!courses[k]||!Array.isArray(rows))throw new Error('The data pack has an unknown course or invalid rows.');next[k]=normalize(rows,k)}data={g10:[],g11:[],g12:[],...next};isDemo=false;setupStudents()}
$('course').onchange=setupStudents;$('student').onchange=setupAssessments;$('assessment').onchange=render;$('criterion').onchange=render;$('studentTab').onclick=()=>{view='student';setupCriteria()};$('classTab').onclick=()=>{view='class';setupCriteria()};$('dataBtn').onclick=()=>{$('importCourse').value=$('course').value;$('dataDialog').showModal()};$('methodBtn').onclick=()=>$('methodDialog').showModal();document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('printBtn').onclick=()=>window.print();$('demoBtn').onclick=()=>{data=demo();isDemo=true;setupStudents();$('dataDialog').close()};$('clearBtn').onclick=()=>{data={g10:[],g11:[],g12:[]};isDemo=false;setupStudents();$('importStatus').textContent='Imported responses cleared from this session.'};
$('file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Choose a file smaller than 10 MB.');if(file.name.toLowerCase().endsWith('.json'))importPack(JSON.parse(await file.text()));else{if(typeof XLSX==='undefined')throw new Error('Excel import is unavailable. Use the prepared JSON data pack.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'}),rows=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:null}),c=$('importCourse').value,headers=rows.shift();if(!headers||!headers.some(x=>String(x).includes('What strategies'))||!headers.some(x=>String(x).includes(c==='g10'?'Criterion':'Which Topic')))throw new Error('The workbook does not match the selected course survey.');if(isDemo)data={g10:[],g11:[],g12:[]};data[c]=normalize(rows,c);isDemo=false;$('course').value=c;setupStudents()}$('importStatus').textContent=`Loaded ${Object.values(data).reduce((a,r)=>a+r.length,0)} responses. Data stays in this session.`;$('dataDialog').close()}catch(err){$('importStatus').textContent=err.message}finally{e.target.value=''}};
